arquivos.somar.py:
def somar_dois_numeros(a: int, b: int) -> int:
    """Retorna a soma de dois inteiros."""
    return a + b

arquivos_teste.test_somar.py:
from somar import somar_dois_numeros


def test_somar_numeros_positivos():
    assert somar_dois_numeros(2, 3) == 5


def test_somar_com_zero():
    assert somar_dois_numeros(0, 5) == 5
    assert somar_dois_numeros(5, 0) == 5


def test_somar_numeros_negativos():
    assert somar_dois_numeros(-2, -3) == -5


def test_somar_positivo_e_negativo():
    assert somar_dois_numeros(10, -4) == 6
